from collections import deque
H,W=d.shape
seen=np.zeros_like(d,bool); comps=[]
for i in range(H):
    for j in range(W):
        if d[i,j] and not seen[i,j]:
            q=deque([(i,j)]); seen[i,j]=1; cells=[]
